class GalleryManager{constructor(){this.config={grid:{desktop:{rows:2,gap:6,minWidth:300},tablet:{rows:2,gap:4,minWidth:200},mobile:{rows:2,gap:4,minWidth:150}},swipe:{threshold:50},preload:{enabled:!0,adjacentImages:1}};this.images=[{id:1,src:"img/gallery/1200x800/1.webp",srcMobile:"img/gallery/800x600/1.webp",thumbnail:"img/gallery/400x300/1.webp",alt:"Prekrasan prikaz prirode 1"},{id:2,src:"img/gallery/1200x800/2.webp",srcMobile:"img/gallery/800x600/2.webp",thumbnail:"img/gallery/400x300/2.webp",alt:"Moderna arhitektura 2"},{id:3,src:"img/gallery/1200x800/3.webp",srcMobile:"img/gallery/800x600/3.webp",thumbnail:"img/gallery/400x300/3.webp",alt:"Gradski vidik noću 3"},{id:4,src:"img/gallery/1200x800/4.webp",srcMobile:"img/gallery/800x600/4.webp",thumbnail:"img/gallery/400x300/4.webp",alt:"Planinski pejzaž 4"},{id:5,src:"img/gallery/1200x800/5.webp",srcMobile:"img/gallery/800x600/5.webp",thumbnail:"img/gallery/400x300/5.webp",alt:"Morska obala 5"},{id:6,src:"img/gallery/1200x800/6.webp",srcMobile:"img/gallery/800x600/6.webp",thumbnail:"img/gallery/400x300/6.webp",alt:"Šumska staza 6"},{id:7,src:"img/gallery/1200x800/7.webp",srcMobile:"img/gallery/800x600/7.webp",thumbnail:"img/gallery/400x300/7.webp",alt:"Gradska četvrt 7"},{id:8,src:"img/gallery/1200x800/8.webp",srcMobile:"img/gallery/800x600/8.webp",thumbnail:"img/gallery/400x300/8.webp",alt:"Zimski pejzaž 8"},{id:9,src:"img/gallery/1200x800/9.webp",srcMobile:"img/gallery/800x600/9.webp",thumbnail:"img/gallery/400x300/9.webp",alt:"Pustinjski krajolik 9"},{id:10,src:"img/gallery/1200x800/10.webp",srcMobile:"img/gallery/800x600/10.webp",thumbnail:"img/gallery/400x300/10.webp",alt:"Jezerski vidik 10"},{id:11,src:"img/gallery/1200x800/11.webp",srcMobile:"img/gallery/800x600/11.webp",thumbnail:"img/gallery/400x300/11.webp",alt:"Planinski vrh 11"},{id:12,src:"img/gallery/1200x800/12.webp",srcMobile:"img/gallery/800x600/12.webp",thumbnail:"img/gallery/400x300/12.webp",alt:"Šumski potok 12"},{id:13,src:"img/gallery/1200x800/13.webp",srcMobile:"img/gallery/800x600/13.webp",thumbnail:"img/gallery/400x300/13.webp",alt:"Poljski cvijet 13"},{id:14,src:"img/gallery/1200x800/14.webp",srcMobile:"img/gallery/800x600/14.webp",thumbnail:"img/gallery/400x300/14.webp",alt:"Gradska noć 14"}];this.state={currentIndex:0,rotatingImages:[],currentRotatingIndex:0,isAnimating:!1,prevIndex:0,swipeStartX:0,isSwiping:!1,isLoading:!1};this.intervals={};this.elements={};this.isInitialized=!1;this.handleKeyDown=this.handleKeyDown.bind(this);this.handleResize=this.handleResize.bind(this);this.handleTouchStart=this.handleTouchStart.bind(this);this.handleTouchMove=this.handleTouchMove.bind(this);this.handleTouchEnd=this.handleTouchEnd.bind(this);this.handleMouseDown=this.handleMouseDown.bind(this);this.handleMouseMove=this.handleMouseMove.bind(this);this.handleMouseUp=this.handleMouseUp.bind(this);this.handlePopState=this.handlePopState.bind(this)}
init(){if(this.isInitialized)return;try{this.cacheElements();this.createGallery();this.setupEventListeners();this.setupGlobalHistoryHandler();this.isInitialized=!0}catch(error){console.error('Gallery init failed:',error)}}
open(imageIndex=0){if(imageIndex<0||imageIndex>=this.images.length)return;if(this.elements.modal.style.display==='block')return;this.state.currentIndex=imageIndex;this.state.prevIndex=imageIndex;this.openModal()}
close(){this.closeModal()}
closeModalWithoutHistory(){if(this.elements.modal.style.display==='none')return;this.elements.modal.classList.remove('active');setTimeout(()=>{this.elements.modal.style.display='none';document.body.style.overflow='auto';this.cleanupModalEventListeners();this.cleanupSwipeEvents();if(this.state.rotatingImages.length>1){this.startRotation()}},150)}
next(){if(this.state.isAnimating)return;this.navigate(1)}
prev(){if(this.state.isAnimating)return;this.navigate(-1)}
getResponsiveSource(image){const width=window.innerWidth;const isMobile=width<768;if(isMobile&&image.srcMobile){return image.srcMobile}
return image.src}
getThumbnailSource(image){return image.thumbnail}
preloadAdjacentImages(currentIndex){if(!this.config.preload.enabled)return;const{adjacentImages}=this.config.preload;for(let i=1;i<=adjacentImages;i++){const prevIndex=(currentIndex-i+this.images.length)%this.images.length;const nextIndex=(currentIndex+i)%this.images.length;this.preloadSingleImage(this.images[prevIndex]);this.preloadSingleImage(this.images[nextIndex])}}
preloadSingleImage(image){const src=this.getResponsiveSource(image);const img=new Image();img.src=src}
showLoading(){this.state.isLoading=!0;this.elements.modalImage.classList.add('loading');let spinner=document.querySelector('.gallery-loading-spinner');if(!spinner){spinner=document.createElement('div');spinner.className='gallery-loading-spinner';this.elements.modalImageContainer.appendChild(spinner)}
spinner.classList.add('active')}
hideLoading(){this.state.isLoading=!1;this.elements.modalImage.classList.remove('loading');const spinner=document.querySelector('.gallery-loading-spinner');if(spinner){spinner.classList.remove('active')}}
cacheElements(){const elements={gallery:'#gallery',modal:'#gallery-modal',modalImage:'#gallery-modal-image',modalImageContainer:'#gallery-modal-image-container',closeBtn:'#gallery-close-btn',prevBtn:'#gallery-prev-btn',nextBtn:'#gallery-next-btn',imageIndicators:'#gallery-image-indicators'};for(const[key,selector]of Object.entries(elements)){this.elements[key]=document.querySelector(selector);if(!this.elements[key]&&key!=='imageIndicators'){throw new Error(`Element not found: ${selector}`)}}}
createGallery(){this.elements.gallery.innerHTML='';this.stopRotation();const visibleCount=this.setupGridLayout();const displayedImages=this.images.slice(0,visibleCount-1);this.state.rotatingImages=this.images.slice(visibleCount-1);displayedImages.forEach((image,index)=>{this.elements.gallery.appendChild(this.createGalleryItem(image))});if(this.state.rotatingImages.length>0){this.elements.gallery.appendChild(this.createRotatingItem());if(this.state.rotatingImages.length>1){this.startRotation()}}}
createGalleryItem(image){const item=document.createElement('div');item.className='gallery-item';const img=document.createElement('img');img.src=this.getThumbnailSource(image);img.alt=image.alt;img.loading='lazy';img.addEventListener('click',()=>{this.state.currentIndex=this.images.findIndex(img=>img.id===image.id);this.state.prevIndex=this.state.currentIndex;this.openModal()});item.appendChild(img);return item}
createRotatingItem(){const item=document.createElement('div');const hasMultipleImages=this.state.rotatingImages.length>1;item.className=hasMultipleImages?'gallery-item rotating-item':'gallery-item rotating-item no-rotation';this.state.rotatingImages.forEach((image,index)=>{const img=document.createElement('img');img.src=this.getThumbnailSource(image);img.alt=image.alt;img.dataset.imageId=image.id;if(hasMultipleImages){img.className=`rotating-image ${index === 0 ? 'active' : ''}`}
item.appendChild(img)});if(hasMultipleImages){const moreText=document.createElement('div');moreText.className='more-text';moreText.textContent=`+${this.state.rotatingImages.length - 1}`;item.appendChild(moreText)}
item.addEventListener('click',()=>{const activeImage=item.querySelector('.rotating-image.active')||item.querySelector('img');if(activeImage){const imageId=parseInt(activeImage.dataset.imageId);this.state.currentIndex=this.images.findIndex(img=>img.id===imageId);this.state.prevIndex=this.state.currentIndex;this.openModal()}});return item}
startRotation(){this.stopRotation();this.intervals.rotation=setInterval(()=>this.rotateImages(),2500)}
stopRotation(){if(this.intervals.rotation){clearInterval(this.intervals.rotation);this.intervals.rotation=null}}
rotateImages(){const rotatingItem=document.querySelector('.rotating-item');if(!rotatingItem)return;const images=rotatingItem.querySelectorAll('.rotating-image');if(images.length===0){this.stopRotation();return}
const currentActive=rotatingItem.querySelector('.rotating-image.active');if(currentActive)currentActive.classList.remove('active');this.state.currentRotatingIndex=(this.state.currentRotatingIndex+1)%images.length;images[this.state.currentRotatingIndex].classList.add('active')}
setupSwipeEvents(){const container=this.elements.modalImageContainer;if(!container)return;container.addEventListener('touchstart',this.handleTouchStart,{passive:!1});container.addEventListener('touchmove',this.handleTouchMove,{passive:!1});container.addEventListener('touchend',this.handleTouchEnd);container.addEventListener('mousedown',this.handleMouseDown);container.addEventListener('mousemove',this.handleMouseMove);container.addEventListener('mouseup',this.handleMouseUp);container.addEventListener('mouseleave',this.handleMouseUp);container.addEventListener('dragstart',(e)=>e.preventDefault())}
handleTouchStart(e){if(this.state.isAnimating)return;this.state.swipeStartX=e.touches[0].clientX;this.state.isSwiping=!0}
handleTouchMove(e){if(!this.state.isSwiping||this.state.isAnimating)return;const touch=e.touches[0];const swipeX=touch.clientX-this.state.swipeStartX;if(Math.abs(swipeX)>10)e.preventDefault();}
handleTouchEnd(e){if(!this.state.isSwiping||this.state.isAnimating)return;const touch=e.changedTouches[0];this.processSwipe(touch.clientX-this.state.swipeStartX);this.state.isSwiping=!1}
handleMouseDown(e){if(this.state.isAnimating||e.button!==0)return;this.state.swipeStartX=e.clientX;this.state.isSwiping=!0;document.body.style.userSelect='none'}
handleMouseMove(e){}
handleMouseUp(e){if(!this.state.isSwiping||this.state.isAnimating)return;this.processSwipe(e.clientX-this.state.swipeStartX);this.state.isSwiping=!1;document.body.style.userSelect=''}
processSwipe(swipeX){if(Math.abs(swipeX)>this.config.swipe.threshold){swipeX>0?this.prev():this.next()}}
cleanupSwipeEvents(){const container=this.elements.modalImageContainer;if(!container)return;const events=['touchstart','touchmove','touchend','mousedown','mousemove','mouseup','mouseleave'];events.forEach(event=>{container.removeEventListener(event,this[`handle${event.charAt(0).toUpperCase() + event.slice(1)}`])})}
openModal(){if(this.elements.modal.style.display==='block')return;this.stopRotation();this.elements.modal.style.display='block';document.body.style.overflow='hidden';const currentState=history.state;if(!currentState||currentState.modal!=='gallery'||currentState.index!==this.state.currentIndex){window.history.pushState({modal:'gallery',index:this.state.currentIndex},'',`#gallery-${this.state.currentIndex}`)}
setTimeout(()=>{this.elements.modal.classList.add('active')},10);this.createIndicators();this.updateModalImage(!0);this.setupSwipeEvents();this.setupModalEventListeners()}
closeModal(){if(this.elements.modal.style.display==='none')return;this.elements.modal.classList.remove('active');setTimeout(()=>{this.elements.modal.style.display='none';document.body.style.overflow='auto';this.cleanupModalEventListeners();this.cleanupSwipeEvents();const currentState=history.state;if(currentState&&currentState.modal==='gallery'){window.history.back()}
if(this.state.rotatingImages.length>1){this.startRotation()}},150)}
navigate(direction){if(this.state.isAnimating)return;this.state.prevIndex=this.state.currentIndex;this.state.currentIndex=(this.state.currentIndex+direction+this.images.length)%this.images.length;window.history.replaceState({modal:'gallery',index:this.state.currentIndex},'',`#gallery-${this.state.currentIndex}`);this.updateModalImage()}
updateModalImage(skipAnimation=!1){const currentImage=this.images[this.state.currentIndex];const responsiveSrc=this.getResponsiveSource(currentImage);this.preloadAdjacentImages(this.state.currentIndex);if(skipAnimation){this.elements.modalImage.src=responsiveSrc;this.elements.modalImage.alt=currentImage.alt;this.updateIndicators();return}
this.state.isAnimating=!0;const direction=this.getNavigationDirection();this.elements.modalImage.classList.add(direction==='next'?'slide-out-left':'slide-out-right');setTimeout(()=>{this.elements.modalImage.classList.remove('slide-out-left','slide-out-right');this.elements.modalImage.src=responsiveSrc;this.elements.modalImage.alt=currentImage.alt;this.elements.modalImage.classList.add(direction==='next'?'slide-in-right':'slide-in-left');this.updateIndicators();setTimeout(()=>{this.elements.modalImage.classList.remove('slide-in-left','slide-in-right');this.state.isAnimating=!1},250)},250)}
getNavigationDirection(){const diff=this.state.currentIndex-this.state.prevIndex;return(diff===1||diff===-(this.images.length-1))?'next':'prev'}
createIndicators(){if(!this.elements.imageIndicators)return;this.elements.imageIndicators.innerHTML='';this.images.forEach((_,index)=>{const indicator=document.createElement('div');indicator.className=`gallery-indicator ${index === this.state.currentIndex ? 'active' : ''}`;indicator.addEventListener('click',()=>{if(this.state.isAnimating)return;this.state.prevIndex=this.state.currentIndex;this.state.currentIndex=index;window.history.replaceState({modal:'gallery',index:this.state.currentIndex},'',`#gallery-${this.state.currentIndex}`);this.updateModalImage()});this.elements.imageIndicators.appendChild(indicator)})}
updateIndicators(){const indicators=document.querySelectorAll('.gallery-indicator');indicators.forEach((indicator,index)=>{indicator.classList.toggle('active',index===this.state.currentIndex)})}
setupGlobalHistoryHandler(){window.addEventListener('popstate',this.handlePopState)}
handlePopState(event){const state=event.state;if(!state){if(this.elements.modal.style.display==='block'){this.closeModalWithoutHistory()}
return}
if(state.modal==='gallery'){if(this.elements.modal.style.display==='block'){this.closeModalWithoutHistory()}else if(state.index!==undefined&&this.elements.modal.style.display==='none'){this.state.currentIndex=state.index;this.state.prevIndex=state.index;this.openModal()}}}
setupGridLayout(){const config=this.getCurrentConfig();const containerWidth=this.elements.gallery.parentElement.clientWidth;const maxColumns=Math.floor(containerWidth/config.minWidth);const itemsPerRow=Math.min(maxColumns,Math.ceil(this.images.length/config.rows));this.elements.gallery.style.gridTemplateColumns=`repeat(${itemsPerRow}, 1fr)`;this.elements.gallery.style.gap=`${config.gap}px`;return itemsPerRow*config.rows}
getCurrentConfig(){const width=window.innerWidth;if(width>=1200)return this.config.grid.desktop;if(width>=768)return this.config.grid.tablet;return this.config.grid.mobile}
setupEventListeners(){if(this.elements.closeBtn){this.elements.closeBtn.addEventListener('click',()=>this.closeModal())}
if(this.elements.modal){this.elements.modal.addEventListener('click',(e)=>{if(e.target===this.elements.modal)this.closeModal();})}
if(this.elements.prevBtn){this.elements.prevBtn.addEventListener('click',(e)=>{e.stopPropagation();this.prev()})}
if(this.elements.nextBtn){this.elements.nextBtn.addEventListener('click',(e)=>{e.stopPropagation();this.next()})}
window.addEventListener('resize',this.handleResize)}
handleResize(){clearTimeout(this.intervals.resize);this.intervals.resize=setTimeout(()=>{this.createGallery()},250)}
setupModalEventListeners(){document.addEventListener('keydown',this.handleKeyDown)}
handleKeyDown(e){switch(e.key){case 'Escape':this.closeModal();break;case 'ArrowLeft':this.prev();break;case 'ArrowRight':this.next();break}}
cleanupModalEventListeners(){document.removeEventListener('keydown',this.handleKeyDown)}
cleanup(){this.stopRotation();this.cleanupModalEventListeners();this.cleanupSwipeEvents();window.removeEventListener('popstate',this.handlePopState);if(this.intervals.resize){clearTimeout(this.intervals.resize)}
this.isInitialized=!1}}
if(!window.galleryManager){window.galleryManager=new GalleryManager()}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',()=>{setTimeout(()=>window.galleryManager.init(),100)})}else{setTimeout(()=>window.galleryManager.init(),100)}